// SPDX-License-Identifier: GPL-3.0
pragma solidity >=0.8.2 <0.9.0;

contract CompMapping {

    uint256 secuencial = 100;

    //struct
    struct Empleado {

        string nombre;
        uint edad;

    }

    /*struct Cuentas {

        address cuenta;
        uint saldo;

    }*/


    mapping(uint => Empleado) private empleados; //mapping de los empleados)

    function getEmpleado(uint _id)public view returns (string memory _nombre, uint _edad){

        Empleado memory emp = empleados[_id];
        return (emp.nombre, emp.edad);
    }

    function addEmpleado(uint id, string memory _nombre, uint _edad) public {

        empleados[id] = Empleado(_nombre, _edad);
    }

    function addEmpleadoSecuencial(string memory _nombre, uint _edad) public {

        empleados[secuencial] = Empleado(_nombre, _edad);
        secuencial ++;
    }
}

contracts/15.EjercicioMensajería.sol.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity >=0.8.2 <0.9.0;

contract EjercicioMensajeria{

    address public owner;

    struct Mensaje {
        address from;
        address to;
        string contenido;
        uint256 timestamp;
    }

    Mensaje[] public historial;

    event NuevoMensaje(address indexed from, address indexed to, string contenido, uint256 timestamp);

    constructor(){

        owner = msg.sender;

    }

    function enviarMensaje(address _to, string memory _contenido) public {

        require(msg.sender == owner, "Solo el propietario puede enviar mensajes");

        Mensaje memory mensajeParaGuardar = Mensaje({
            from: owner,
            to: _to,
            contenido: _contenido,
            timestamp: block.timestamp
        });

        historial.push(mensajeParaGuardar);

        emit NuevoMensaje(msg.sender, _to, _contenido, block.timestamp);
    }
}
